package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }

    /**
     * Test Case 1: findConvertingContentDeserializer returns null, 
     * and findContextualValueDeserializer returns the default String deserializer.
     * Result: deser becomes null via isDefaultDeserializer check.
     * Return: 'this' (the original deserializer).
     */
    @Test
    public void testCreateContextual_DefaultStringDeserializerReturnsThis() throws JsonMappingException {
        // We need to mock the internal behavior. Since we can't easily mock protected findConvertingContentDeserializer 
        // without a spy, we use a spy to control the flow.
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        // Mock findConvertingContentDeserializer to return null
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // Mock findContextualValueDeserializer to return the default String deserializer
        JsonDeserializer<?> defaultStringDeser = new StringDeserializer();
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(defaultStringDeser);

        // The isDefaultDeserializer check in the real code is likely checking if it's a standard String deserializer
        // Since we can't easily mock isDefaultDeserializer (it's private/protected), 
        // we rely on the fact that a new StringDeserializer is considered default.

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals("Should return 'this' when result is the default deserializer", spyDeserializer, result);
    }

    /**
     * Test Case 2: findConvertingContentDeserializer returns a non-null deserializer.
     * The deserializer is not the default one.
     * Result: Returns a new StringArrayDeserializer wrapping the new deserializer.
     */
    @Test
    public void testCreateContextual_ReturnsNewWrapperWhenDeserializerChanges() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        JsonDeserializer<?> customDeser = mock(JsonDeserializer.class);

        // 1. findConvertingContentDeserializer returns customDeser
        doReturn(customDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());

        // 2. Since deser != null, it calls handleSecondaryContextualization
        // We mock it to return the same customDeser to avoid infinite recursion in the mock
        when(ctxt.handleSecondaryContextualization(eq(customDeser), eq(property))).thenReturn(customDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotSame("Result should be a new instance", spyDeserializer, result);
        assertTrue("Result should be a StringArrayDeserializer", result instanceof StringArrayDeserializer);
    }

    /**
     * Test Case 3: findConvertingContentDeserializer returns null, 
     * and findContextualValueDeserializer returns a non-default custom deserializer.
     * Result: Returns a new StringArrayDeserializer.
     */
    @Test
    public void testCreateContextual_ReturnsNewWrapperWhenContextualDeserializerFound() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());
        JsonDeserializer<?> customDeser = mock(JsonDeserializer.class);

        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(customDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertNotSame(spyDeserializer, result);
        assertTrue(result instanceof StringArrayDeserializer);
    }

    /**
     * Test Case 4: findConvertingContentDeserializer returns null, 
     * findContextualValueDeserializer returns null.
     * Result: deser is null.
     * Return: 'this'.
     */
    @Test
    public void testCreateContextual_AllNullReturnsThis() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals(spyDeserializer, result);
    }

    /**
     * Test Case 5: findConvertingContentDeserializer returns a deserializer,
     * but handleSecondaryContextualization returns the EXACT same deserializer as _elementDeserializer.
     * Result: Returns 'this'.
     */
    @Test
    public void testCreateContextual_ReturnsThisWhenDeserializerIsSame() throws JsonMappingException {
        // To test this, we need _elementDeserializer to be set. 
        // Since it's likely private, we use the spy to return it.
        JsonDeserializer<?> existingDeser = mock(JsonDeserializer.class);
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        // We must use reflection to set the private field _elementDeserializer if we want to test the equality branch
        try {
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(spyDeserializer, existingDeser);
        } catch (Exception e) {
            fail("Failed to set private field");
        }

        doReturn(existingDeser).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.handleSecondaryContextualization(eq(existingDeser), eq(property))).thenReturn(existingDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals(spyDeserializer, result);
    }
}
